+'use strict';
+
+const crypto = require('node:crypto');
+const fs = require('node:fs');
+const path = require('node:path');
+const { execFileSync } = require('node:child_process');
+const processLock = require('../process_lock.js');
+
+const DEFAULT_ROOT = path.resolve(__dirname, '..');
+const SCHEMA_VERSION = 1;
+const MAX_LOCK_WAIT_MS = 30 * 60 * 1000;
+const LOCK_POLL_MS = 250;
+const TRANSIENT_ENV_NAMES = new Set([
+  'PWD', 'OLDPWD', 'TMP', 'TMPDIR', 'TEMP', 'TEMPDIR', 'SHLVL', '_',
+  'TERM', 'TERM_PROGRAM', 'TERM_PROGRAM_VERSION', 'COLORTERM',
+  'CLICOLOR', 'CLICOLOR_FORCE', 'FORCE_COLOR', 'NO_COLOR',
+  'HERDR_PROJECTS_ID', 'HERDR_PROJECTS_TASK_ID', 'HERDR_PROJECTS_RUN_ID',
+  'HERDR_PROJECTS_WORKER_ID', 'SECURITYSESSIONID', 'SSH_AUTH_SOCK', 'XPC_FLAGS', 'XPC_SERVICE_NAME',
+]);
+
+function sha256(value) {
+  return crypto.createHash('sha256').update(value).digest('hex');
+}
+
+function envFingerprint(env) {
+  const rows = Object.entries(env)
+    .filter(([name]) => !TRANSIENT_ENV_NAMES.has(name.toUpperCase()) && !/^(?:HEAVY|CODEX|HERDR|CLAUDE_CODE|CURSOR)_/.test(name.toUpperCase()))
+    .sort(([left], [right]) => left < right ? -1 : left > right ? 1 : 0)
+    .map(([name, value]) => [sha256(name), sha256(String(value))]);
+  return sha256(JSON.stringify(rows));
+}
+
+function argsFingerprint(argv) {
+  const args = argv.filter((argument) => argument !== '--force');
+  return sha256(JSON.stringify(args));
+}
+
+function gitEnv() {
+  const env = { ...process.env };
+  for (const name of Object.keys(env)) {
+    if (/^GIT_(?:DIR|WORK_TREE|COMMON_DIR|INDEX_FILE|OBJECT_DIRECTORY|ALTERNATE_OBJECT_DIRECTORIES|CEILING_DIRECTORIES|PREFIX|CONFIG(?:_.+)?|TRACE(?:_.+)?|OPTIONAL_LOCKS)$/i.test(name)) {
+      delete env[name];
+    }
+  }
+  env.GIT_OPTIONAL_LOCKS = '0';
+  env.GIT_TERMINAL_PROMPT = '0';
+  return env;
+}
+
+function gitOutput(root, args) {
+  try {
+    return execFileSync('git', ['-C', root, ...args], {
+      encoding: 'utf8',
+      env: gitEnv(),
+      maxBuffer: 64 * 1024 * 1024,
+      stdio: ['ignore', 'pipe', 'ignore'],
+    });
+  } catch {
+    throw new Error('Unable to inspect the release gate checkout with Git');
+  }
+}
+
+function isCleanCheckout(root) {
+  const status = gitOutput(root, [
+    '--no-optional-locks', 'status', '--porcelain=v1', '-z',
+    '--untracked-files=all', '--ignore-submodules=none',
+  ]);
+  return status.length === 0;
+}
+
+function regularFileSha256(filePath) {
+  const stat = fs.lstatSync(filePath);
+  if (!stat.isFile() || stat.isSymbolicLink()) throw new Error('Expected a regular file');
+  return sha256(fs.readFileSync(filePath));
+}
+
