+  ['feature-gate', 'test_srw19_feature_gate.js', []],
+  ['index-lotto', 'test_srw16_release_gate.js', ['--step', 'index-lotto']],
+  ['copy-trading', 'test_srw16_release_gate.js', ['--step', 'copy-trading']],
+  ['intake-refusals', 'test_srw16_release_gate.js', ['--step', 'intake-refusals']],
+  ['stale-protective', 'test_srw16_release_gate.js', ['--step', 'stale-protective']],
+  ...Array.from({ length: 8 }, (_, i) => [`chase-${i}`, 'test_srw16_release_gate.js', ['--step', `chase-${i}`]]),
+  ...['test_telegram_desk_risk.js', 'test_telegram_refusal_replies.js', 'test_telegram_clef_classifier.js']
+    .map(file => [file, file, []]),
+];
+
+async function run() {
+  const jobsAt = process.argv.indexOf('--jobs');
+  const jobs = jobsAt < 0 ? Math.min(2, os.availableParallelism()) : Number(process.argv[jobsAt + 1]);
+  if (!Number.isInteger(jobs) || jobs < 1 || jobs > 2) throw new Error('--jobs must be 1 or 2');
+  const scheduleAt = process.argv.indexOf('--schedule');
+  const schedule = scheduleAt < 0 ? 'fifo' : process.argv[scheduleAt + 1];
+  if (!['fifo', 'longest', 'grouped'].includes(schedule)) throw new Error('unknown gate schedule');
