+  if (schedule === 'fifo') steps.sort((a, b) => a[0].localeCompare(b[0]));
+  if (schedule === 'grouped') {
+    steps = steps.filter(([name]) => !name.startsWith('chase-'));
+    steps.push(['chase-all', 'test_srw16_release_gate.js', ['--step', 'chase-all']]);
+  }
+  const start = performance.now();
+  const results = [];
+  const active = new Set();
+  let next = 0;
+  let failure;
+  let signal;
+  const escalation = new Map();
+  const terminate = child => {
+    child.kill('SIGTERM');
+    if (!escalation.has(child)) {
+      const timer = setTimeout(() => child.kill('SIGKILL'), 5000);
+      timer.unref();
+      escalation.set(child, timer);
+    }
+  };
