+      console.log(`gate: start ${name}`);
+      try {
+        await new Promise((resolve, reject) => {
+          const child = spawn(process.execPath, [path.join(ROOT, file), ...args], {
+            cwd: ROOT, stdio: ['ignore', 'inherit', 'inherit'],
